-- Reihe 1 · Bauform NF-1 (fkt_quadr_normalform), erzeugt von tools/bauform.sh (scripts/bauformen/bauformen/nf_1.py).
-- Steckbrief und 68 gruene Instanzen (Status draft, Pool session). Pruefmaschine: 68 gruen,
-- 4 rot (verworfen). Blindloeser: {"geloest": 10, "abweichend": [], "bestanden": true}.
-- Vorschau: docs/reihe1/A/bauformen/NF-1.json. Aendert sich der Steckbrief, steigt die Version (Trigger); die
-- Instanzen tragen die neue Version, die alten bleiben fuer die Historie. Der Steckbrief enthaelt den Hash des
-- Generators: aendert sich der Generator, steigt die Version ebenfalls.
--
-- Pruefabfrage: select count(*) from tasks t join bauformen b on b.id = t.bauform_id
--                where b.schluessel = 'NF-1' and t.bauform_version = b.version;   → 68
do $$ begin perform set_config('edvance.bauform_export', '1', true); end $$;
insert into public.bauformen (schluessel, skill_key, kernidee_key, format, rollen, steckbrief, generator_pfad, status,
                              pruefprotokoll, blindloeser, verdacht)
values ('NF-1', 'fkt_quadr_normalform', 'fkt_quadr_normalform:K1', 'feldmaske', '{warmup,uebung,home}'::text[],
        '{"text": "Schreib f(x) = {term} in der Normalform.", "stufen": {"1": "f(x) = (x − d)² + e, d und e von 1 bis 9", "2": "d und e mit beliebigem Vorzeichen", "3": "f(x) = a(x − d)² + e mit a ∈ {−2, −1, 2, 3}"}, "fehlbilder": [{"key": "qf_binom_mittelglied_fehlt", "regel": "x² + d² + e (2dx fehlt)", "gilt_fuer_stufen": [1, 2, 3], "rueckmeldung": "Beim Quadrat einer Klammer gibt es ein mittleres Glied. Multipliziere die Klammer mit sich selbst."}, {"key": "qf_binom_vorzeichen", "regel": "Vorzeichen des Glieds mit x falsch", "gilt_fuer_stufen": [1, 2, 3], "rueckmeldung": "Prüf das Vorzeichen des Glieds mit x. Es hat dasselbe Vorzeichen wie die Zahl in der Klammer."}, {"key": "qf_faktor_nicht_verteilt", "regel": "a nur mit x² multipliziert", "gilt_fuer_stufen": [3], "rueckmeldung": "Die Zahl vor der Klammer gilt für jedes Glied der ausmultiplizierten Klammer."}], "hinweise": ["Multipliziere zuerst das Quadrat aus: (x − d)² = x² − 2dx + d².", "Danach {a_schritt}fasse die Zahlen zusammen.", "Für die Klammer gilt: {klammer}² = {binom}."], "loesungsweg": [], "warum": null, "kontext": null, "figur": null, "zeit_sek": 90, "kann_entfallen": false, "generator_hash": "9daaa63520d3"}'::jsonb, 'scripts/bauformen/bauformen/nf_1.py', 'zur_pruefung',
        '{"gruen": 68, "rot": 4, "rot_anteil": 0.056, "gruende": {"7": 4}, "verdacht": null, "lauf_am": "20261028153548"}'::jsonb, '{"geloest": 10, "abweichend": [], "anteil": 0.0, "bestanden": true, "antworten": {"1": "Feld 1: 2, Vorzeichen: +, Feld 2: 28, Vorzeichen: +, Feld 3: 102", "2": "Vorzeichen: −, Feld 1: 12, Vorzeichen: +, Feld 2: 45", "3": "Vorzeichen: −, Feld 1: 14, Vorzeichen: +, Feld 2: 44", "4": "Vorzeichen: −, Feld 1: 8, Vorzeichen: +, Feld 2: 22", "5": "Vorzeichen: +, Feld 1: 2, Vorzeichen: −, Feld 2: 7", "6": "Vorzeichen: −, Feld 1: 6, Vorzeichen: +, Feld 2: 15", "7": "Vorzeichen: −, Feld 1: 4, Vorzeichen: +, Feld 2: 11", "8": "Vorzeichen: −, Feld 1: 6, Vorzeichen: +, Feld 2: 18", "9": "Vorzeichen: −, Feld 1: 2, Vorzeichen: +, Feld 2: 4", "10": "Vorzeichen: +, Feld 1: 2, Vorzeichen: +, Feld 2: 9"}}'::jsonb, null)
on conflict (schluessel) do update
   set skill_key = excluded.skill_key, kernidee_key = excluded.kernidee_key, format = excluded.format,
       rollen = excluded.rollen, steckbrief = excluded.steckbrief, generator_pfad = excluded.generator_pfad,
       pruefprotokoll = excluded.pruefprotokoll, blindloeser = excluded.blindloeser, verdacht = excluded.verdacht,
       -- Lenas Entscheidung bleibt, solange sich nichts aendert; eine neue Version oeffnet der Trigger.
       status = case when excluded.verdacht is not null then 'entwurf'
                     when bauformen.status = 'entwurf' then 'zur_pruefung'
                     else bauformen.status end;

