 7)² = x² − 14x + 49.", "status": "entwurf"}]}, {"suffix": "home-s3-c728edf5dd", "input_type": "FELDMASKE", "frage": "Schreib f(x) = −2(x − 4)² + 7 in der Normalform.", "payload": {"format": "feldmaske", "schablone": [{"feld": "a", "typ": "zahl"}, {"text": "x² "}, {"feld": "vb", "typ": "vorzeichen"}, {"feld": "b", "typ": "zahl"}, {"text": "x "}, {"feld": "vc", "typ": "vorzeichen"}, {"feld": "c", "typ": "zahl"}]}, "params": {"a": -2, "d": 4, "e": 7}, "stufe": 3, "rolle": "home", "pm": {"1": {"ok": true}, "2": {"ok": true}, "3": {"ok": true}, "4": {"ok": true}, "5": {"ok": true}, "6": {"ok": true}, "7": {"ok": true}}, "afb": "II", "correct": [{"werte": {"a": "-2", "b": "16", "c": "-25"}, "fehlbilder": [{"key": "qf_binom_mittelglied_fehlt", "werte": {"a": "-2", "b": "0", "c": "-25"}}, {"key": "qf_binom_vorzeichen", "werte": {"a": "-2", "b": "-16", "c": "-25"}}, {"key": "qf_faktor_nicht_verteilt", "werte": {"a": "-2", "b": "-8", "c": "23"}}]}], "acceptance": null, "parts": null, "figur": null, "optionen": null, "solution": "f(x) = −2(x − 4)² + 7\n= −2(x² − 8x + 16) + 7\n= −2x² + 16x − 25", "hints": [{"level": 1, "text": "Multipliziere zuerst das Quadrat aus: (x − d)² = x² − 2dx + d².", "status": "entwurf"}, {"level": 2, "text": "Danach multiplizierst du jedes Glied mit −2 und fasse die Zahlen zusammen.", "status": "entwurf"}, {"level": 3, "text": "Für die Klammer gilt: (x − 4)² = x² − 8x + 16.", "status": "entwurf"}]}]'::jsonb)
             as v(suffix text, input_type text, frage text, payload jsonb, params jsonb, stufe int, rolle text,
                  pm jsonb, afb text, correct jsonb, acceptance jsonb, parts jsonb, figur jsonb, optionen jsonb,
                  solution text, hints jsonb)),
     neu as (
  insert into public.tasks (content_type, input_type, status, is_active, title, question, question_payload, parts, skill_key,
                            difficulty, afb, class_level, est_duration_sec, source, source_ref, einsatz, bauform_id,
                            bauform_version, params, stufe, rolle, kernidee_key, pruefmaschine)
  select 'exercise', v.input_type, 'draft', true, 'NF-1' || ' · ' || v.rolle || ' · S' || v.stufe, v.frage,
         v.payload, coalesce(v.parts, '[]'::jsonb), 'fkt_quadr_normalform', v.stufe, v.afb, 9, 90, 'bauform',
         'NF-1' || '-v' || b.version || '-' || v.suffix, '{session}', b.id, b.version, v.params, v.stufe,
         v.rolle, 'fkt_quadr_normalform:K1', v.pm
    from b, v
  on conflict (source, source_ref) do nothing
  returning id, source_ref),
     loes as (
  insert into public.task_solutions (task_id, correct_answers, acceptance, solution, hints)
  select neu.id, v.correct, v.acceptance, v.solution, v.hints
    from neu join b on true join v on neu.source_ref = 'NF-1' || '-v' || b.version || '-' || v.suffix
  returning task_id),
     fig as (
  -- Eine Figur je Aufgabe (task_figures) bzw. je Option einer Graph-Auswahl (task_figur_optionen); hochgeladen
  -- werden sie von scripts/figures/upload_figures.py (Rasit).
  insert into public.task_figures (task_id, generator, params, alt_text)
  select neu.id, v.figur ->> 'generator', v.figur -> 'params', v.figur ->> 'alt'
    from neu join b on true join v on neu.source_ref = 'NF-1' || '-v' || b.version || '-' || v.suffix
   where v.figur is not null
  returning task_id)
insert into public.task_figur_optionen (task_id, option_id, generator, params, alt_text)
select neu.id, o ->> 'option', o ->> 'generator', o -> 'params', o ->> 'alt'
  from neu join b on true join v on neu.source_ref = 'NF-1' || '-v' || b.version || '-' || v.suffix,
       jsonb_array_elements(coalesce(v.optionen, '[]')) o;
do $$ begin perform set_config('edvance.hinweis_status', '', true); perform set_config('edvance.bauform_export', '', true); end $$;
